    data = sys.stdin.read().split()
    n = int(data[0])
    odd = set()
    for x in data[1:1 + 2 * n]:
        v = int(x)
        if v in odd:
            odd.remove(v)
        else:
            odd.add(v)
    print('true' if not odd else 'false')

